pub assume_specification<T, F, K>[ core::cmp::max_by_key ](
    v1: T,
    v2: T,
    f: F,
) -> (result: T)
where
    F: FnMut(&T) -> K,
    K: core::cmp::Ord,
    requires
        K::obeys_partial_cmp_spec(),
        f.requires((&v2,)),
        f.requires((&v1,)),
        forall|key2a: K, key2b: K|
            #![trigger f.ensures((&v2,), key2a), f.ensures((&v2,), key2b)]
            f.ensures((&v2,), key2a)
                && f.ensures((&v2,), key2b)
                ==> key2a == key2b,
        forall|key1a: K, key1b: K|
            #![trigger f.ensures((&v1,), key1a), f.ensures((&v1,), key1b)]
            f.ensures((&v1,), key1a)
                && f.ensures((&v1,), key1b)
                ==> key1a == key1b,
    ensures
        exists|key2: K| {
            &&& #[trigger] f.ensures((&v2,), key2)
            &&& exists|key1: K| {
                &&& #[trigger] f.ensures((&v1,), key1)
                &&& result == if key2.partial_cmp_spec(&key1)
                    == Some(core::cmp::Ordering::Less)
                {
                    v1
                } else {
                    v2
                }
            }
        },
;

#[verifier::external_trait_specification]
pub trait ExIteratorMax {
    type ExternalTraitSpecificationFor: core::iter::Iterator;
    type Item;

    fn max(self) -> (r: Option<Self::Item>)
    where
        Self: Sized,
        Self::Item: Ord,
    requires
        <Self::Item as OrdSpec>::obeys_cmp_spec(),
    default_ensures
        {
            let s = into_iter_remaining::<Self::Item, Self>(self);
            r == if s.len() == 0 {
                None
            } else {
                Some(s.drop_first().fold_left(
                    s[0],
                    |x: Self::Item, y: Self::Item| if <Self::Item as OrdSpec>::cmp_spec(&x, &y) == Ordering::Greater { x } else { y },
                ))
            }
        },
    ;
}

pub assume_specification<B, C>[ ControlFlow::<B, C>::continue_ok ](
    flow: ControlFlow<B, C>,
) -> (result: Result<C, B>)
    ensures
        result == match flow {
            ControlFlow::Continue(c) => Ok(c),
            ControlFlow::Break(b) => Err(b),
        },
    no_unwind
;

pub assume_specification<B, C, T, F>[ ControlFlow::<B, C>::map_break ](
    flow: ControlFlow<B, C>,
    f: F,
) -> (res: ControlFlow<T, C>)
where
    F: FnOnce(B) -> T,
    requires
        match flow {
            ControlFlow::Break(b) => f.requires((b,)),
            ControlFlow::Continue(_) => true,
        },
    ensures
        match flow {
            ControlFlow::Continue(c) => res == ControlFlow::Continue(c),
            ControlFlow::Break(b) => match res {
                ControlFlow::Break(t) => f.ensures((b,), t),
                ControlFlow::Continue(_) => false,
            },
        },
;

pub assume_specification<B, C, T, F>[ ControlFlow::<B, C>::map_continue ](
    flow: ControlFlow<B, C>,
    f: F,
) -> (res: ControlFlow<B, T>)
where
    F: FnOnce(C) -> T,
    requires
        match flow {
            ControlFlow::Continue(c) => f.requires((c,)),
            ControlFlow::Break(_) => true,
        },
    ensures
        match flow {
            ControlFlow::Break(b) => res == ControlFlow::Break(b),
            ControlFlow::Continue(c) => match res {
                ControlFlow::Continue(t) => f.ensures((c,), t),
                ControlFlow::Break(_) => false,
            },
        },
;

