pub assume_specification<'a, T, B: core::cmp::Ord, F: FnMut(&'a T) -> B>[ <[T]>::binary_search_by_key ](
    slice: &'a [T],
    b: &B,
    f: F,
) -> (result: Result<usize, usize>)
    requires
        forall|i: int| 0 <= i < slice@.len() ==> f.requires((&slice@[i],)),
    ensures
        slice.len() == 0 ==> result == Result::<usize, usize>::Err(0),
        result is Ok ==> {
            &&& result->Ok_0 < slice.len()
            &&& exists|key: B| {
                &&& f.ensures((&slice@[result->Ok_0 as int],), key)
                &&& call_ensures(
                    <B as core::cmp::Ord>::cmp,
                    (&key, b),
                    Ordering::Equal,
                )
            }
        },
        result is Err ==> result->Err_0 <= slice.len(),
;

